{
  "scene_id": "s1:scene:0001",
  "omitted_earlier_translated_blocks": 0,
  "blocks": [
    {
      "block_id": "s1:block:00009-00019",
      "page_role": "narration",
      "speaker_en": null,
      "jp": "港町ミルフェ……辺境にありながらも海洋産業と鉱石の産出、\n更には、交易の中継地として栄える独立都市\n今回の旅の目的地であるこの街へと辿り着いた俺は\nその中央に位置する広場に入った所で足を止めた\n途中まで乗っていた、この街へ向かう船が座礁し、\n陸路を歩いて旅を続けてきた俺の身体は、目的地に\n着いた安堵感により、心地よい程度の疲労を感じている\n普段、疲労とは無縁の俺は、新鮮なその感覚が嬉しく思えた",
      "en": "Milfe, a port town. Though on the frontier, it prospers as an independent city from marine industry, mineral ore, and trade. I arrived at my destination and stopped in the central plaza. The ship I had boarded partway ran aground, so I continued overland. Now, with relief, my body feels a pleasant fatigue. Normally, I am never fatigued, so I enjoyed the fresh sensation."
    },
    {
      "block_id": "s1:block:00021-00022",
      "page_role": "dialogue",
      "speaker_en": "Celica",
      "jp": "………………？",
      "en": "......?"
    },
    {
      "block_id": "s1:block:00024-00024",
      "page_role": "narration",
      "speaker_en": null,
      "jp": "不意に違和感を覚え、自分の胸元を開き覗き見る",
      "en": "Feeling odd, I opened my shirt and looked."
    },
    {
      "block_id": "s1:block:00029-00030",
      "page_role": "dialogue",
      "speaker_en": "Celica",
      "jp": "………………………………………",
      "en": "........................................."
    },
    {
      "block_id": "s1:block:00032-00033",
      "page_role": "narration",
      "speaker_en": null,
      "jp": "俺はれっきとした男だが、其処には僅かではあるが、\n男にあるべきではない膨らみがある",
      "en": "I am unmistakably a man, yet there is a slight swelling there that should not exist on a man."
    },
    {
      "block_id": "s1:block:00035-00040",
      "page_role": "dialogue",
      "speaker_en": "Celica",
      "jp": "………………………………………\n（忘れていた………………\nあまり無理をしないほうがいいな……………）",
      "en": "......\n(I had forgotten......\nI should not overdo it......)"
    },
    {
      "block_id": "s1:block:00042-00042",
      "page_role": "narration",
      "speaker_en": null,
      "jp": "疲労により生まれた身体の変化に俺は自らに反省を促す",
      "en": "I reflect on the bodily change my fatigue caused."
    },
    {
      "block_id": "s1:block:00044-00045",
      "page_role": "dialogue",
      "speaker_en": "Shuri",
      "jp": "やっと着きましたね、御主人様",
      "en": "We have finally arrived, Master."
    },
    {
      "block_id": "s1:block:00051-00064",
      "page_role": "narration",
      "speaker_en": null,
      "jp": "其の声に胸元を閉じた俺は顔を上げ其の声の主を振り返った\n大きな荷物を背負った少女が俺を見上げている。\nこの娘の名はシュリ、諸般の事情により今回の旅に\n同行させる事になった家の使用人だ。\nこの娘は昔戦災孤児となった所を俺に拾われ、以来\n家で使用人として働き、主に俺の身の回りの世話等を\nしてくれている。\n幼い頃から家で働いている事もあってか、使用人の中では特に\n従順かつ献身的で器量も良いのだが、最近では年相応に\n落ち着いてきたのか、俺に対して一歩引いた態度を\nとるようになってきているのが物寂しくもある……。",
      "en": "At that voice, I closed my shirt, raised my face, and turned toward the speaker. A girl with a large bundle on her back looks up at me. Her name is Shuri. Due to various circumstances, she is a servant from my household, brought along on this journey. I took her in as a war orphan long ago, and since then she has worked in my house, mainly tending to my personal needs. Perhaps because she has served since childhood, she is especially obedient and devoted among the servants, and quite capable as well. But lately, perhaps having matured with age, she has begun to keep a certain respectful distance toward me... and I find that a little lonely."
    }
  ]
}

